    local cf = KB_CONF[li]
    local lv = LEVELS[li]
    lv.TRACE = tr
    lv.ZOOM = 0.92
    lv.DECOR = {}
    lv.SPAWN = cf.spawn
    lv.CPS = cf.cps
    lv.GOAL = cf.goal
    lv.KILL = cf.kill
    lv.PAL.player = cf.player
    -- 预计算各层多边形包围盒(渲染裁剪)
    for _, lay in ipairs(tr.layers) do
        lay.bb = {}
        for pi, fp in ipairs(lay.polys) do
            local x1, y1, x2, y2 = 1e9, 1e9, -1e9, -1e9
            for k = 1, #fp - 1, 2 do
                local x, y = fp[k], fp[k + 1]
                if x < x1 then x1 = x end
                if x > x2 then x2 = x end
                if y < y1 then y1 = y end
                if y > y2 then y2 = y end
            end
            lay.bb[pi] = { x1, y1, x2, y2 }
        end
    end
    -- 碰撞多边形 + 包围盒
    local polys = {}
    for _, lay in ipairs(tr.layers) do
        if lay.coll == 1 then
            for pi, fp in ipairs(lay.polys) do
                local poly = {}
                for k = 1, #fp - 1, 2 do
                    poly[#poly + 1] = { fp[k], fp[k + 1] }
                end
                poly.bb = lay.bb[pi]
                polys[#polys + 1] = poly
            end
        end
    end
    lv.POLYS = polys
end

