local curLevel = 1
local LV = LEVELS[1]
local cpReached = {}

local function insidePoly(poly, x, y)
    local n = #poly
    local inside = false
    for i = 1, n do
        local ax, ay = poly[i][1], poly[i][2]
        local bx, by = poly[i % n + 1][1], poly[i % n + 1][2]
        if (ay > y) ~= (by > y) then
            local ix = ax + (y - ay) / (by - ay) * (bx - ax)
            if ix > x then inside = not inside end
        end
    end
    return inside
end

-- 从 (x, y-100) 向下找最近的"顶面"(交点下方 5px 在实体内),不改关卡数据
local function snapToGround(x, y)
    local bestY = nil
    for _, poly in ipairs(LV.POLYS) do
        local bb = poly.bb
        if (not bb) or (x >= bb[1] - 4 and x <= bb[3] + 4) then
            local n = #poly
            for i = 1, n do
                local ax, ay = poly[i][1], poly[i][2]
                local bx, by = poly[i % n + 1][1], poly[i % n + 1][2]
                if (ax < x) ~= (bx < x) and math.abs(bx - ax) > 1e-6 then
                    local t = (x - ax) / (bx - ax)
                    local iy = ay + (by - ay) * t
                    if iy >= y - 100 and iy <= y + 1400 then
                        if (bestY == nil or iy < bestY) and insidePoly(poly, x, iy + 5) then
                            bestY = iy
                        end
                    end
                end
            end
        end
    end
    if bestY then return bestY - 2 end
    return y
end

local curCPS = {}

local function loadLevel(n)
    curLevel = clamp(n, 1, #LEVELS)
    LV = LEVELS[curLevel]
    spawnX = LV.SPAWN[1]
    spawnY = snapToGround(LV.SPAWN[1], LV.SPAWN[2]) - 12
    curCPS = {}
    for i, cp in ipairs(LV.CPS) do
        curCPS[i] = { cp[1], snapToGround(cp[1], cp[2]) - 12 }
    end
    P.x, P.y = spawnX, spawnY - 30
    P.vx, P.vy = 0, 0
    P.isDashing = false
    P.canDash = true
    camX, camY = P.x, P.y - 50
    tpts = {}
    droplets = {}
    burstFx = {}
    goalDone, goalAge = false, 0
    cpReached = {}
    for i = 1, #LV.CPS do cpReached[i] = (i == 1) end
    print("[kingsbird] level " .. curLevel .. " " .. LV.name)
end

-- ---------------- 碰撞 ----------------
local function collideCircle(px, py, pr)
    local pushX, pushY = 0, 0
    local hitGround, hitWallDir = false, 0
    for _, poly in ipairs(LV.POLYS) do
        local bb = poly.bb
        if bb and (px + pr < bb[1] or px - pr > bb[3] or py + pr < bb[2] or py - pr > bb[4]) then
            goto next_poly
        end
        local n = #poly
        -- 内部检测(射线法)+ 最近边
        local inside = false
        local bestD2, bestX, bestY = 1e18, 0, 0
        for i = 1, n do
            local ax, ay = poly[i][1], poly[i][2]
            local bx, by = poly[i % n + 1][1], poly[i % n + 1][2]
            if ((ay > py) ~= (by > py)) then
                local ix = ax + (py - ay) / (by - ay) * (bx - ax)
                if ix > px then inside = not inside end
            end
            local ex, ey = bx - ax, by - ay
            local L2 = ex * ex + ey * ey
            if L2 > 1e-6 then
                local t = clamp(((px - ax) * ex + (py - ay) * ey) / L2, 0, 1)
                local cx, cy = ax + ex * t, ay + ey * t
                local dx, dy = px - cx, py - cy
                local d2 = dx * dx + dy * dy
                if d2 < bestD2 then bestD2, bestX, bestY = d2, cx, cy end
            end
        end
        if inside then
            -- 卡入实体:朝最近边外侧弹出
            local dx, dy = bestX - px, bestY - py
            local d = math.sqrt(dx * dx + dy * dy)
            local nx, ny
            if d > 1e-4 then nx, ny = dx / d, dy / d else nx, ny = 0, -1 end
            px = bestX + nx * (pr + 1)
            py = bestY + ny * (pr + 1)
            pushX = pushX + nx * (d + pr)
            pushY = pushY + ny * (d + pr)
            if ny < -0.55 then hitGround = true end
            if nx > 0.75 then hitWallDir = -1 end
            if nx < -0.75 then hitWallDir = 1 end
            goto next_poly
        end
        for i = 1, n do
            local ax, ay = poly[i][1], poly[i][2]
            local bx, by = poly[i % n + 1][1], poly[i % n + 1][2]
            local ex, ey = bx - ax, by - ay
            local L2 = ex * ex + ey * ey
            if L2 > 1e-6 then
                local t = clamp(((px - ax) * ex + (py - ay) * ey) / L2, 0, 1)
                local cx, cy = ax + ex * t, ay + ey * t
                local dx, dy = px - cx, py - cy
                local d2 = dx * dx + dy * dy
                if d2 < pr * pr and d2 > 1e-9 then
                    local d = math.sqrt(d2)
                    local nx, ny = dx / d, dy / d
                    local push = pr - d
                    px = px + nx * push
                    py = py + ny * push
                    pushX = pushX + nx * push
                    pushY = pushY + ny * push
                    if ny < -0.55 then hitGround = true end
                    if nx > 0.75 then hitWallDir = -1 end
                    if nx < -0.75 then hitWallDir = 1 end
                end
            end
        end
        ::next_poly::
    end
    return px, py, pushX, pushY, hitGround, hitWallDir
end

-- ---------------- 拖尾骨架 ----------------
local function trailAddPoint(tx, ty, vel)
    local tension = (dashInterp > 0.5) and 0.93 or 0.65
    local nx, ny = tx, ty
    if #tpts > 0 then
        local head = tpts[#tpts]
        nx = head.x + (tx - head.x) * tension
        ny = head.y + (ty - head.y) * tension
        local dx, dy = nx - head.x, ny - head.y
        accumDist = accumDist + math.sqrt(dx * dx + dy * dy)
    end
    tpts[#tpts + 1] = { x = nx, y = ny, dist = accumDist, vel = vel }
    local maxLen = (dashInterp > 0.5) and 116 or 58
    while #tpts > maxLen do table.remove(tpts, 1) end
end

local function spawnDroplet(x, y, dashing)
    local ang = math.random() * math.pi * 2
    local eject = dashing and (2.2 + math.random() * 6.5) or (0.5 + math.random() * 1.5)
    droplets[#droplets + 1] = {
        x = x, y = y,
        vx = -P.vx * (dashing and 0.38 or 0.15) + math.cos(ang) * eject * 0.4,
        vy = math.sin(ang) * eject * 0.4 + (dashing and (-1.0 - math.random() * 2.0) or 0.4),
        r = dashing and (0.6 + math.random() * 1.8) or (2.0 + math.random() * 3.5),
        life = 1.0,
        decay = dashing and (0.022 + math.random() * 0.03) or (0.015 + math.random() * 0.015),
        streak = dashing,
    }
end

-- ---------------- 物理 ----------------
local function respawn()
    print(string.format("[kb] respawn at lv%d (was %.0f,%.0f)", curLevel, P.x, P.y))
    if not P.landedSinceSpawn then
        P.respawnFails = (P.respawnFails or 0) + 1
        if P.respawnFails >= 2 then
            -- 当前存档点不可活,退回关卡起点
            spawnX, spawnY = LV.SPAWN[1], LV.SPAWN[2]
            P.respawnFails = 0
            print("[kb] bad checkpoint, fall back to level spawn")
        end
    else
        P.respawnFails = 0
    end
    P.landedSinceSpawn = false
    P.x, P.y = spawnX, spawnY - 30
    P.vx, P.vy = 0, 0
    P.isDashing = false
    P.canDash = true
    tpts = {}
    droplets = {}
end

local function fixedStep()
    elapsed = elapsed + FIXED_DT

    if P.dashQueued then
        if P.canDash and not P.isDashing then
            local dx = (keys.d and 1 or 0) - (keys.a and 1 or 0)
            local dy = (keys.s and 1 or 0) - (keys.w and 1 or 0)
            if dx == 0 and dy == 0 then dx = P.facing end
            local d = math.sqrt(dx * dx + dy * dy)
            P.isDashing = true
            P.canDash = false
            P.dashTime = 12
            P.dashVisualT = 46
            P.dashDirX, P.dashDirY = dx / d, dy / d
        end
        P.dashQueued = false
    end

    if P.isDashing then
        P.dashTime = P.dashTime - 1
        P.vx = P.dashDirX * P.dashSpeed
        P.vy = P.dashDirY * P.dashSpeed
        if P.dashTime <= 0 then
            P.isDashing = false
            P.vx = P.vx * 0.5
        end
    else
        if keys.a then P.vx = P.vx - P.accel; P.facing = -1 end
        if keys.d then P.vx = P.vx + P.accel; P.facing = 1 end
        P.vy = P.vy + P.grav
        P.vx = P.vx * P.fric
        if P.wallDir ~= 0 and not P.grounded and P.vy > 3.0
            and ((P.wallDir == -1 and keys.a) or (P.wallDir == 1 and keys.d)) then
            P.vy = 3.0
        end
    end

    if P.jumpQueued then
        if P.grounded or P.coyote > 0 then
            P.vy = -P.jumpV
            P.grounded = false
            P.coyote = 0
        elseif P.wallDir ~= 0 then
            P.vx = -P.wallDir * 9.5
            P.vy = -13
            P.facing = -P.wallDir
            P.canDash = true
        end
        P.jumpQueued = false
    end

    if LV.UPDRAFTS then
        for _, u in ipairs(LV.UPDRAFTS) do
            local dx, dy = P.x - u[1], P.y - u[2]
            if dx * dx + dy * dy < u[3] * u[3] and not P.isDashing then
                P.vy = math.max(P.vy - 1.25, -9.5)
            end
        end
    end

    local spdSum = math.abs(P.vx) + math.abs(P.vy)
    local steps = math.max(1, math.ceil(spdSum / 5.5))
    local hitG, hitW = false, 0
    for _ = 1, steps do
        P.x = P.x + P.vx / steps
        P.y = P.y + P.vy / steps
        local nx, ny, pX, pY, g, w = collideCircle(P.x, P.y, P.r)
        P.x, P.y = nx, ny
        if g then hitG = true end
        if w ~= 0 then hitW = w end
        if pX ~= 0 or pY ~= 0 then
            local pl = math.sqrt(pX * pX + pY * pY)
            local nnx, nny = pX / pl, pY / pl
            local vn = P.vx * nnx + P.vy * nny
            if vn < 0 then
                P.vx = P.vx - nnx * vn
                P.vy = P.vy - nny * vn
            end
        end
    end
    P.grounded = hitG
    P.wallDir = hitW
    if hitG then P.landedSinceSpawn = true end
    -- 双保险:连续 30 帧速度被钳为 0 且按键有输入 -> 视为卡死回档
    if (keys.a or keys.d) and math.abs(P.vx) < 0.05 and math.abs(P.vy) < 0.05 and not P.grounded then
        P.stuckT = (P.stuckT or 0) + 1
        if P.stuckT > 30 then
            P.stuckT = 0
            respawn()
        end
    else
        P.stuckT = 0
    end
    if P.grounded then
        P.coyote = 6
        P.canDash = true
    elseif P.coyote > 0 then
        P.coyote = P.coyote - 1
    end

    for i, cp in ipairs(curCPS) do
        if not cpReached[i] then
            local dx, dy = P.x - cp[1], P.y - cp[2]
            if dx * dx + dy * dy < 70 * 70 then
                cpReached[i] = true
                spawnX, spawnY = cp[1], cp[2]
                burstFx[#burstFx + 1] = { x = cp[1], y = cp[2] - 30, age = 0, kind = "cp" }
            end
        end
    end
    if not goalDone then
        local dx, dy = P.x - LV.GOAL[1], P.y - LV.GOAL[2]
        if dx * dx + dy * dy < 90 * 90 then
            goalDone = true
            goalAge = 0
            burstFx[#burstFx + 1] = { x = LV.GOAL[1], y = LV.GOAL[2], age = 0, kind = "goal" }
        end
    else
        goalAge = goalAge + 1
        if goalAge == 100 then loadLevel(curLevel % #LEVELS + 1) end
    end
    if P.y > LV.KILL then respawn() end

    if (P.dashVisualT or 0) > 0 then P.dashVisualT = P.dashVisualT - 1 end
    local spd = math.sqrt(P.vx * P.vx + P.vy * P.vy)
    local stretched = P.isDashing or (P.dashVisualT or 0) > 0 or spd > 13.5
    dashInterp = dashInterp + ((stretched and 1 or 0) - dashInterp) * 0.16
    trailAddPoint(P.x, P.y, spd)
    if spd < 0.8 and #tpts > 0 then table.remove(tpts, 1) end

    for i = #droplets, 1, -1 do
        local d = droplets[i]
        d.x = d.x + d.vx
        d.y = d.y + d.vy
        d.vy = d.vy + 0.06
        d.vx = d.vx * 0.96
        d.life = d.life - d.decay
        if d.life <= 0 then table.remove(droplets, i) end
    end
    for _, b in ipairs(burstFx) do b.age = b.age + 1 end
    for i = #burstFx, 1, -1 do if burstFx[i].age > 70 then table.remove(burstFx, i) end end

    camX = camX + (P.x - camX) * 0.07
    camY = camY + (P.y - 50 - camY) * 0.06
    if LV.TRACE then
        local halfW = (screenW / 2) / (LV.ZOOM or CAM_ZOOM)
        local halfH = (screenH / 2) / (LV.ZOOM or CAM_ZOOM)
        local sx1 = LV.TRACE.spanx[1] + halfW * 0.0
        local sx2 = LV.TRACE.spanx[2] + 1680
        camX = clamp(camX, math.min(sx1 + halfW, 840), math.max(sx2 - halfW, 840))
        local sy1 = LV.TRACE.spany[1]
        local sy2 = LV.TRACE.spany[2] + 910
        if sy2 - sy1 <= halfH * 2 then
            camY = (sy1 + sy2) / 2
        else
            camY = clamp(camY, sy1 + halfH, sy2 - halfH)
        end
    end
end

-- ============================================================================
-- 渲染:通用元素
-- ============================================================================
local function skyGradient(w, h)
    local PAL = LV.PAL
    if LV.TRACE then
        nvgBeginPath(vg)
        nvgRect(vg, 0, 0, w, h)
        nvgFillColor(vg, rgba(LV.TRACE.base[1], LV.TRACE.base[2], LV.TRACE.base[3], 255))
        nvgFill(vg)
        return
    end
    local bands = 64
    for i = 0, bands - 1 do
        local t = i / (bands - 1)
        local c
        if t < 0.5 then c = lerpC(PAL.skyT, PAL.skyM, t * 2)
        else c = lerpC(PAL.skyM, PAL.skyL, (t - 0.5) * 2) end
        nvgBeginPath(vg)
        nvgRect(vg, 0, h * i / bands - 1, w, h / bands + 2)
        nvgFillColor(vg, col(c))
        nvgFill(vg)
    end
end

local function drawGlow(x, y, r, c, a)
    for i = 6, 1, -1 do
        nvgBeginPath(vg)
        nvgCircle(vg, x, y, r * i / 6 * 1.8)
        nvgFillColor(vg, col(c, a / (i * 3.2)))
        nvgFill(vg)
    end
    nvgBeginPath(vg)
    nvgCircle(vg, x, y, r * 0.5)
    nvgFillColor(vg, col(c, a))
    nvgFill(vg)
end

-- 斜射光柱(神庙/森林)
local function drawGodRays(px, py)
    local c = LV.PAL.rayCol
    for i = 0, 5 do
        local rx = i * 1100 + hash01(i + 3) * 500 - px * 0.2
        nvgBeginPath(vg)
        nvgMoveTo(vg, rx, -400)
        nvgLineTo(vg, rx + 240, -400)
        nvgLineTo(vg, rx - 500 + 240, 2600)
        nvgLineTo(vg, rx - 500 - 60 - hash01(i) * 200, 2600)
        nvgClosePath(vg)
        nvgFillColor(vg, col(c, 22 + hash01(i * 7) * 14))
        nvgFill(vg)
    end
end

-- 拱廊列(横排连续拱门)
local function drawArchRow(x, y, w, ah, aw, c, alpha)
    nvgFillColor(vg, col(c, alpha))
    local n = math.floor(w / aw)
    for k = 0, n - 1 do
        local ax = x + k * aw
        nvgBeginPath(vg)
        nvgRect(vg, ax + aw * 0.12, y - ah * 0.55, aw * 0.76, ah * 0.55)
        nvgCircle(vg, ax + aw * 0.5, y - ah * 0.55, aw * 0.38)
        nvgFill(vg)
    end
end

-- 栏杆带
local function drawBalustrade(x, y, w, c, alpha)
    nvgStrokeColor(vg, col(c, alpha))
    nvgStrokeWidth(vg, 3)
    nvgBeginPath(vg)
    nvgMoveTo(vg, x, y - 22)
    nvgLineTo(vg, x + w, y - 22)
    nvgStroke(vg)
    nvgStrokeWidth(vg, 2)
    for k = 0, math.floor(w / 26) do
        nvgBeginPath(vg)
        nvgMoveTo(vg, x + k * 26, y)
        nvgLineTo(vg, x + k * 26, y - 22)
        nvgStroke(vg)
    end
end

-- 漂浮描线方块
local function drawSquares(d)
    nvgStrokeWidth(vg, 2)
    for k = 1, d.n do
        local sx = d.x + hash01(d.seed + k * 3) * d.w
        local sy = d.y + hash01(d.seed + k * 7) * d.h + math.sin(elapsed * 0.6 + k) * 6
        local ss = 8 + hash01(d.seed + k * 13) * 26
        nvgStrokeColor(vg, col(LV.PAL.sqCol or LV.PAL.acc, (LV.PAL.sqA or 36) + hash01(d.seed + k) * 34))
        nvgBeginPath(vg)
        nvgRect(vg, sx, sy, ss, ss * (0.6 + hash01(k) * 0.5))
        nvgStroke(vg)
    end
end

-- 卷草纹(森林雕饰螺线)
local function drawCurl(x, y)
    nvgStrokeColor(vg, col(LV.PAL.mid, 200))
    nvgStrokeWidth(vg, 7)
    nvgBeginPath(vg)
    for k = 0, 20 do
        local a = k / 20 * math.pi * 2.1
        local r = 56 * (1 - k / 26)
        local px = x + math.cos(a) * r
        local py = y + math.sin(a) * r
        if k == 0 then nvgMoveTo(vg, px, py) else nvgLineTo(vg, px, py) end
    end
    nvgStroke(vg)
end

-- 垂藤
local function drawVine(x, y, len)
    nvgStrokeColor(vg, col(LV.PAL.fore, 235))
    nvgStrokeWidth(vg, 3.5)
    local sway = math.sin(elapsed * 0.9 + x * 0.01) * 9
    nvgBeginPath(vg)
    nvgMoveTo(vg, x, y)
    nvgBezierTo(vg, x + sway * 0.4, y + len * 0.4, x + sway, y + len * 0.75, x + sway * 1.3, y + len)
    nvgStroke(vg)
    nvgBeginPath(vg)
    nvgCircle(vg, x + sway * 1.3, y + len, 4.5)
    nvgFillColor(vg, col(LV.PAL.fore))
    nvgFill(vg)
end

-- 灯柱
local function drawLampPost(x, y)
    nvgStrokeColor(vg, col(LV.PAL.fore))
    nvgStrokeWidth(vg, 5)
    nvgBeginPath(vg)
    nvgMoveTo(vg, x, y)
    nvgLineTo(vg, x, y - 56)
    nvgStroke(vg)
    nvgBeginPath(vg)
    nvgMoveTo(vg, x, y - 56)
    nvgBezierTo(vg, x + 16, y - 62, x + 22, y - 50, x + 25, y - 42)
    nvgStrokeWidth(vg, 3.5)
    nvgStroke(vg)
    drawGlow(x + 25, y - 36, 9, { 255, 245, 220 }, 200)
end

-- 亭顶(水城凉亭塔冠)
local function drawKiosk(x, y, w)
    local PAL = LV.PAL
    local cx = x + w / 2
    nvgFillColor(vg, col(PAL.foreDk or PAL.fore))
    nvgBeginPath(vg)
    nvgMoveTo(vg, x - 26, y)
    nvgBezierTo(vg, x + w * 0.2, y - 64, x + w * 0.8, y - 64, x + w + 26, y)
    nvgClosePath(vg)
    nvgFill(vg)
    nvgBeginPath(vg)
    nvgCircle(vg, cx, y - 58, 9)
    nvgFill(vg)
    nvgStrokeColor(vg, col(PAL.foreDk or PAL.fore))
    nvgStrokeWidth(vg, 4)
    nvgBeginPath(vg)
    nvgMoveTo(vg, cx, y - 64)
    nvgLineTo(vg, cx, y - 102)
    nvgStroke(vg)
    nvgBeginPath(vg)
    nvgCircle(vg, cx, y - 106, 5)
    nvgFill(vg)
end

-- 灯串
local function drawLampString(x1, y1, x2, y2)
    nvgStrokeColor(vg, col(LV.PAL.foreDk or LV.PAL.fore, 200))
    nvgStrokeWidth(vg, 2.4)
    local midx, midy = (x1 + x2) / 2, (y1 + y2) / 2 + 46
    nvgBeginPath(vg)
    nvgMoveTo(vg, x1, y1)
    nvgBezierTo(vg, midx, midy, midx, midy, x2, y2)
    nvgStroke(vg)
    for k = 1, 5 do
        local t = k / 6
        local bx = lerp(lerp(x1, midx, t), lerp(midx, x2, t), t)
        local by = lerp(lerp(y1, midy, t), lerp(midy, y2, t), t)
        drawGlow(bx, by + 8, 5, { 255, 250, 235 }, 170)
    end
end

-- 绿藤板(紫废墟点缀)
local function drawGreenPanel(x, y, w, h)
    nvgFillColor(vg, rgba(100, 146, 84, 230))
    nvgBeginPath(vg)
    nvgRect(vg, x, y, w, h)
    nvgFill(vg)
    -- 垂叶条纹
    for k = 0, math.floor(w / 22) do
        local lx = x + k * 22 + 8
        local ll = h * (0.4 + hash01(lx) * 0.7)
        nvgStrokeColor(vg, rgba(76, 120, 62, 220))
        nvgStrokeWidth(vg, 6)
        nvgBeginPath(vg)
        nvgMoveTo(vg, lx, y)
        nvgBezierTo(vg, lx + 4, y + ll * 0.5, lx - 3, y + ll * 0.8, lx + 2, y + ll)
        nvgStroke(vg)
    end
    -- 底缘叶团
    nvgFillColor(vg, rgba(86, 134, 70, 235))
    for k = 0, math.floor(w / 26) do
        nvgBeginPath(vg)
        nvgCircle(vg, x + k * 26 + 12, y + h - 4 + hash01(k) * 10, 11 + hash01(k * 3) * 6)
        nvgFill(vg)
    end
end

-- 倾斜石板(装饰)
local function drawSlab(d)
    nvgSave(vg)
    nvgTranslate(vg, d.x, d.y)
    nvgRotate(vg, d.rot)
    nvgFillColor(vg, col(LV.PAL.fore, 245))
    nvgBeginPath(vg)
    nvgRect(vg, -d.w / 2, -d.h / 2, d.w, d.h)
    nvgFill(vg)
    nvgRestore(vg)
end

-- ============================================================================
-- 渲染:各关背景(远/中景)
-- ============================================================================
local function bgGoldTemple(px, py)
    local PAL = LV.PAL
    -- 远景:连续金光拱窗墙(整面)
    nvgFillColor(vg, rgba(112, 128, 84, 200))
    nvgBeginPath(vg)
    nvgRect(vg, px - 2400, -600, 4800, 3200)
    nvgFill(vg)
    local boff = px * 0.75
    local bx0 = math.floor((px - 2400 + boff) / 520) * 520 - boff
    for k = 0, 10 do
        local ax = bx0 + k * 520
        local gi = math.floor((ax + boff) / 520)
        local aw = 300
        local ah = 620 + hash01(gi) * 260
        local ay = 1500 - hash01(gi * 3) * 700
        nvgFillColor(vg, rgba(236, 208, 112, 255))
        nvgBeginPath(vg)
        nvgRect(vg, ax, ay - ah * 0.5, aw, ah)
        nvgCircle(vg, ax + aw / 2, ay - ah * 0.5, aw / 2)
        nvgFill(vg)
    end
    drawGodRays(px, py)
    -- 中景:连续茶绿拱廊带(两层)
    for band = 0, 1 do
        local bandY = 1340 + band * 300
        local boff2 = px * (0.5 - band * 0.06)
        local bx2 = math.floor((px - 2400 + boff2) / 130) * 130 - boff2
        drawArchRow(bx2, bandY, 4900, 250, 130, PAL.mid, band == 0 and 245 or 215)
        drawBalustrade(bx2, bandY - 250 * 0.55 - 8, 4900, PAL.mid, 200)
    end
    -- 中景垂藤帘
    for i = 0, 13 do
        local vx = i * 430 + hash01(i + 31) * 240 - px * 0.5
        nvgStrokeColor(vg, col(PAL.mid, 175))
        nvgStrokeWidth(vg, 4)
        nvgBeginPath(vg)
        nvgMoveTo(vg, vx, -300)
        nvgBezierTo(vg, vx + 26, 200, vx - 20, 600, vx + 12, 820 + hash01(i) * 420)
        nvgStroke(vg)
        nvgBeginPath(vg)
        nvgCircle(vg, vx + 12, 826 + hash01(i) * 420, 6)
        nvgFillColor(vg, col(PAL.mid, 190))
        nvgFill(vg)
    end
end

local function bgMauveRuins(px, py)
