local function bgWaterCity(px, py)
    local PAL = LV.PAL
    -- 淡青云团带
    for i = 0, 11 do
        local cx2 = i * 760 + hash01(i + 3) * 300 - px * 0.12
        local cy2 = 300 + hash01(i + 13) * 500
        nvgFillColor(vg, rgba(208, 248, 250, 200))
        for b = 0, 3 do
            nvgBeginPath(vg)
            nvgCircle(vg, cx2 + b * 110 - 160, cy2 + hash01(b + i) * 60, 110 + hash01(i * 7 + b) * 70)
            nvgFill(vg)
        end
    end
    -- 远景极淡蓝城
    for i = 0, 15 do
        local bx = i * 560 + hash01(i + 7) * 320 - px * 0.2
        local bw = 260 + hash01(i + 16) * 200
        local bh = 500 + hash01(i + 26) * 600
        nvgFillColor(vg, col(PAL.mid2, 220))
        nvgBeginPath(vg)
        nvgRect(vg, bx, 1750 - bh, bw, bh)
        nvgCircle(vg, bx + bw / 2, 1750 - bh, bw * 0.4)
        nvgFill(vg)
    end
    -- 中景薰衣草蓝城(亭塔 + 拱廊)
    for i = 0, 8 do
        local bx = i * 1050 + hash01(i + 33) * 400 - px * 0.45
        local bw = 300 + hash01(i + 43) * 180
        local bh = 700 + hash01(i + 53) * 500
        nvgFillColor(vg, col(PAL.mid, 240))
        nvgBeginPath(vg)
        nvgRect(vg, bx, 1750 - bh, bw, bh)
        nvgFill(vg)
        -- 亭顶
        nvgBeginPath(vg)
        nvgMoveTo(vg, bx - 30, 1750 - bh)
        nvgBezierTo(vg, bx + bw * 0.25, 1750 - bh - 70, bx + bw * 0.75, 1750 - bh - 70, bx + bw + 30, 1750 - bh)
        nvgClosePath(vg)
        nvgFill(vg)
        nvgStrokeColor(vg, col(PAL.mid, 240))
        nvgStrokeWidth(vg, 5)
        nvgBeginPath(vg)
        nvgMoveTo(vg, bx + bw / 2, 1750 - bh - 66)
        nvgLineTo(vg, bx + bw / 2, 1750 - bh - 116)
        nvgStroke(vg)
        -- 拱窗
        nvgFillColor(vg, col(PAL.mid2, 190))
        nvgBeginPath(vg)
        nvgRect(vg, bx + bw * 0.3, 1750 - bh * 0.62, bw * 0.4, bh * 0.28)
        nvgCircle(vg, bx + bw * 0.5, 1750 - bh * 0.62, bw * 0.2)
        nvgFill(vg)
    end
    -- 水面
    nvgFillColor(vg, col(PAL.waterCol))
    nvgBeginPath(vg)
    nvgRect(vg, px - 2200, PAL.water, 4400, 1400)
    nvgFill(vg)
